package com.hbm.client.gascentrifuge;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.machine.gascentrifuge.*;import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.vertex.*;import java.util.*;import net.minecraft.ChatFormatting;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.renderer.GameRenderer;import net.minecraft.client.resources.language.I18n;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
/** Source206x204, exact slots/pixels and top-down four6x52 pseudo-fluid columns. */
public final class GasCentrifugeScreen extends LegacyContainerScreen<GasCentrifugeMenu>{
 public GasCentrifugeScreen(GasCentrifugeMenu menu,Inventory player,Component title){super(menu,player,title,GasCentrifugeContent.id("textures/gui/processing/gui_centrifuge_gas.png"),206,204);}private GasCentrifugeBlockEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position()) instanceof GasCentrifugeBlockEntity m?m:null;}@Override protected void renderLabels(GuiGraphics graphics,int x,int y){graphics.drawString(font,playerInventoryTitle,8,110,4210752,false);}
 @Override protected void renderBg(GuiGraphics graphics,float partial,int x,int y){super.renderBg(graphics,partial,x,y);var m=machine();if(m==null)return;int fill=(int)(m.power*52/GasCentrifugeBlockEntity.MAX_POWER);if(fill>0)drawLegacyRegion(graphics,182,69-fill,206,52-fill,16,fill);if(m.progress>0)drawLegacyRegion(graphics,70,35,206,52,m.progress*36/m.getProcessingSpeed(),13);for(int col:new int[]{16,32})column(graphics,col,m.inputTank.fluid,m.inputTank.maxFluid);for(int col:new int[]{138,154})column(graphics,col,m.outputTank.fluid,m.outputTank.maxFluid);var texture=GasCentrifugeContent.id("textures/gui/gui_utility.png");graphics.blit(texture,leftPos-12,topPos+16,24,0,16,16,256,256);graphics.blit(texture,leftPos-12,topPos+32,8,0,16,16,256,256);}
 private void column(GuiGraphics g,int x,int fill,int max){int amount=fill*52/Math.max(max,1);if(amount<=0)return;var m=machine();g.flush();RenderSystem.setShader(GameRenderer::getPositionTexColorShader);RenderSystem.setShaderTexture(0,m.tank.getTankType().getTexture());RenderSystem.enableBlend();RenderSystem.defaultBlendFunc();var out=Tesselator.getInstance().begin(VertexFormat.Mode.QUADS,DefaultVertexFormat.POSITION_TEX_COLOR);var matrix=g.pose().last().pose();float left=leftPos+x,top=topPos+16;out.addVertex(matrix,left,top+amount,0).setUv(0,1-amount/16F).setColor(-1);out.addVertex(matrix,left+6,top+amount,0).setUv(6/16F,1-amount/16F).setColor(-1);out.addVertex(matrix,left+6,top,0).setUv(6/16F,1).setColor(-1);out.addVertex(matrix,left,top,0).setUv(0,1).setColor(-1);BufferUploader.drawWithShader(out.buildOrThrow());RenderSystem.disableBlend();}
 @Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);var m=machine();if(m==null)return;if(legacyInfoHovered(x,y,15,15,24,55)){var name=m.inputTank.type.displayName();if(m.inputTank.type.highSpeed)name=name.copy().withStyle(m.fast()?ChatFormatting.GOLD:ChatFormatting.DARK_RED);g.renderComponentTooltip(font,List.of(name,Component.literal(m.inputTank.fluid+" / "+m.inputTank.maxFluid+" mB")),x,y);}if(legacyInfoHovered(x,y,137,15,25,55)){var name=m.outputTank.type.displayName();if(m.outputTank.type.highSpeed)name=name.copy().withStyle(ChatFormatting.GOLD);g.renderComponentTooltip(font,List.of(name,Component.literal(m.outputTank.fluid+" / "+m.outputTank.maxFluid+" mB")),x,y);}if(legacyInfoHovered(x,y,182,17,16,52))g.renderTooltip(font,Component.literal(String.format(Locale.US,"%,d / %,d HE",m.power,GasCentrifugeBlockEntity.MAX_POWER)),x,y);if(legacyInfoHovered(x,y,-12,16,16,16))info(g,"desc.gui.gasCent.enrichment",leftPos-8,topPos+32);if(legacyInfoHovered(x,y,-12,32,16,16))info(g,"desc.gui.gasCent.output",leftPos-8,topPos+48);}
 private void info(GuiGraphics g,String key,int x,int y){g.renderComponentTooltip(font,Arrays.stream(I18n.get(key).split("\\$",-1)).map(Component::literal).map(c->(Component)c).toList(),x,y);}
}
